 59	    public Xdg64 createOrderFromBid(Xrd81 user, Xdh20 productSize, int bidPrice) {
 60	        try {
 61	
 62	            if (user == null) {
 63	                throw new Xcz21Exception("사용자 정보가 없습니다.");
 64	            }
 65	            if (productSize == null) {
 66	                throw new Xrf10Exception("상품 사이즈 정보가 없습니다.");
 67	            }
 68	            if (bidPrice <= 0) {
 69	                throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 70	            }
 71	
 72	
 73	            Xhm58 orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
 74	
 75	
 76	            Xdg64 order = Xdg64.builder()
 77	                    .user(user)
 78	                    .totalAmount(bidPrice)
 79	                    .discountAmount(0)
 80	                    .usedPoints(0)
 81	                    .status(Xdg64Status.PENDING_PAYMENT)
 82	                    .build();
 83	
 84	
 85	            order.addOrderItem(orderItem);
 86	
 87	
 88	            return orderRepository.save(order);
 89	        } catch (Exception e) {
 90	            if (e instanceof Xdg64Exception) {
 91	                throw e;
