    public Xbf54 processPayment(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            validatePaymentRequest(order, user, requestDto);

            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());

            Xbf54 payment;

            switch (requestDto.getResolvedPaymentType()) {
                case "CARD":
                    payment = createCardPayment(order, user, (Xqg94RequestDto) requestDto);
                    break;
                case "ACCOUNT":
                    payment = createAccountPayment(order, user, (Xkg34RequestDto) requestDto);
                    break;
                case "GENERAL":
                    payment = createGeneralPayment(order, user, (Xjt86RequestDto) requestDto);
                    break;
                default:
                    throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
            }


            notifyUsersAndUpdateSaleStatus(order, payment);

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), payment.getId(), payment.getStatus());

            return payment;
        } catch (Xbf54Exception e) {
            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",






    @Transactional
    public Xzj27 createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {

            validateCreateOrderBidInput(email, productSizeId, bidPrice);


            Xrd81 user = userQueryService.findByEmail(email);


            Xdh20 productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new Xrf10Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));


            Xdg64 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);


            Xzj27 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null;
        }
    }




    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new Xxd47Exception("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new Xrf10Exception("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }




    private Xzj27 createAndSaveOrderBid(Xrd81 user, Xdh20 productSize, int bidPrice, Xdg64 order) {
        Xzj27 orderBid = Xzj27.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xtz73Status.PENDING)
                .order(order)
                .build();


        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }





    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xrd81 user;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private Xdh20 productSize;

    private int bidPrice;

    @Builder.Default
    @Enumerated(EnumType.STRING)
    private Xtz73Status status = Xtz73Status.PENDING;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xdg64 order;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xgg74 sale;


    @Builder.Default
    @Column(nullable = false)
    private boolean isInstantPurchase = false;







    public void assignOrder(Xdg64 order) {

        if (this.order != null && this.order != order) {
            Xdg64 oldOrder = this.order;
            this.order = null;
            if (oldOrder.getOrderBid() == this) {
                oldOrder.assignOrderBid(null);
            }
        }


        this.order = order;


        if (order != null) {
            this.status = Xtz73Status.MATCHED;


            if (order.getOrderBid() != this) {
                order.assignOrderBid(this);
            }
        }
    }






    public void assignSale(Xgg74 sale) {
        this.sale = sale;
        this.status = Xtz73Status.MATCHED;
    }




    public void markAsInstantPurchase() {
        this.isInstantPurchase = true;
    }






    public void updateStatus(Xtz73Status newStatus) {
        this.status = newStatus;
    }
}

